<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_super_admin();$locs=db()->query('SELECT id,code,name FROM locations WHERE active=1 ORDER BY code')->fetchAll();$err='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$barcode=trim($_POST['barcode']??'');$location=(int)($_POST['location_id']??0);$qty=(float)($_POST['quantity']??0);$kind=$_POST['kind']??'';$remarks=trim($_POST['remarks']??'');if(!in_array($kind,['ADJUST_IN','ADJUST_OUT','DAMAGE'],true)||$qty<=0)$err='Invalid adjustment.';else try{db()->beginTransaction();
 $st=db()->prepare('SELECT ps.*,p.serial_tracking FROM product_serials ps JOIN products p ON p.id=ps.product_id WHERE ps.serial_barcode=? AND ps.location_id=? FOR UPDATE');$st->execute([$barcode,$location]);$serial=$st->fetch();$out=in_array($kind,['ADJUST_OUT','DAMAGE'],true);$productId=$batchId=0;$adjQty=$qty;
 if($serial){if(abs($qty-1)>0.0001)throw new Exception('Unique barcode adjustment quantity must be 1.');$productId=(int)$serial['product_id'];$batchId=(int)$serial['batch_id'];$adjQty=1;if($out&&$serial['status']!=='AVAILABLE')throw new Exception('Unique piece is already unavailable.');if(!$out&&$serial['status']==='AVAILABLE')throw new Exception('Unique piece is already available.');if(!$out&&!in_array($serial['status'],['DAMAGED'],true))throw new Exception('Only a DAMAGED unique piece can be restored by physical adjustment. Sold, reserved or supplier-returned pieces cannot be resurrected here.');}
 else {$st=db()->prepare('SELECT ib.product_id,ib.batch_id,ib.qty,ib.reserved_qty,p.serial_tracking FROM inventory_balances ib JOIN batches b ON b.id=ib.batch_id JOIN products p ON p.id=ib.product_id WHERE ib.location_id=? AND (b.batch_barcode=? OR p.product_barcode=?) ORDER BY b.purchased_at LIMIT 1 FOR UPDATE');$st->execute([$location,$barcode,$barcode]);$r=$st->fetch();if(!$r)throw new Exception('Barcode not found at location.');if((int)$r['serial_tracking']===1)throw new Exception('Serialized garment: scan individual unique barcode.');$productId=(int)$r['product_id'];$batchId=(int)$r['batch_id'];if($out&&((float)$r['qty']-(float)$r['reserved_qty'])<$qty)throw new Exception('Insufficient sellable stock; reserved online stock cannot be adjusted out.');}
 $st=db()->prepare('SELECT qty,reserved_qty FROM inventory_balances WHERE product_id=? AND batch_id=? AND location_id=? FOR UPDATE');$st->execute([$productId,$batchId,$location]);$bal=$st->fetch();if(!$bal)throw new Exception('Inventory balance missing at location.');if($out&&((float)$bal['qty']-(float)$bal['reserved_qty'])<$adjQty)throw new Exception('Insufficient sellable stock; reserved online stock cannot be adjusted out.');$delta=$out?-$adjQty:$adjQty;db()->prepare('UPDATE inventory_balances SET qty=qty+? WHERE product_id=? AND batch_id=? AND location_id=?')->execute([$delta,$productId,$batchId,$location]);db()->prepare('UPDATE batches SET qty_available=qty_available+? WHERE id=?')->execute([$delta,$batchId]);if($serial){$newStatus=$out?'DAMAGED':'AVAILABLE';db()->prepare('UPDATE product_serials SET status=? WHERE id=?')->execute([$newStatus,$serial['id']]);}db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_in,qty_out,reference_type,remarks,created_by) VALUES(?,?,?,?,?,?,'ADJUSTMENT',?,?)")->execute([$kind,$productId,$batchId,$location,$out?0:$adjQty,$out?$adjQty:0,$remarks,current_user()['id']]);if($out)maybe_publish_low_stock($productId,$location);db()->commit();audit('STOCK_'.$kind,'batch',$batchId,['barcode'=>$barcode,'qty'=>$adjQty,'remarks'=>$remarks]);publish_event('STOCK_ADJUST','Stock adjustment',$barcode.' · '.$kind.' · Qty '.number_format($adjQty,0),['super_admin','manager','godown'],'batch',$batchId,$location);$msg='Stock adjustment posted.';
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
page_header('Stock Adjustment / Damage');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row3"><div><label>Barcode</label><input name="barcode" data-scanner class="scanbox" required></div><div><label>Location</label><select name="location_id"><?php foreach($locs as $l):?><option value="<?=$l['id']?>"><?=e($l['code'].' · '.$l['name'])?></option><?php endforeach;?></select></div><div><label>Type</label><select name="kind"><option value="ADJUST_IN">Physical Stock Increase</option><option value="ADJUST_OUT">Physical Stock Decrease</option><option value="DAMAGE">Damage / Write-off</option></select></div></div><br><div class="row"><div><label>Quantity</label><input type="number" step="0.001" min="0.001" name="quantity" value="1" required></div><div><label>Reason / Remarks</label><input name="remarks" required></div></div><br><button class="btn">Post Adjustment</button></form><?php page_footer();
